struct Ring {
    cap = 4
    items = []
    invariant len(self.items) <= self.cap
    fn push(self, x) {
        let next = self.items + [x]
        if len(next) > self.cap { next = next[1..len(next)] }
        self.items = next
    }
    fn mean(self) { self.items.sum() / float(len(self.items)) }
}
let r = Ring()
for i in 1..=6 { r.push(i) }
print(r.items, r.mean())

