challenges.solution:
struct Arm {
    angle = 0
    invariant -90 <= self.angle and self.angle <= 90
}
let arm = Arm()
fn step_toward(arm, target)
    require -90 <= target and target <= 90
{
    let delta = clamp(target - arm.angle, -15, 15)
    arm.angle = arm.angle + delta
}
always arm.angle != 77
let seen = []
while arm.angle != 60 {
    step_toward(arm, 60)
    seen.push(arm.angle)
}
print(seen)

challenges.check:
let bad = false
try { step_toward(arm, 120) } catch e { bad = true }
assert bad, "targets beyond 90 must violate the precondition"

